"""Reports CSV exporter."""


def export_csv(rows, columns):
    """Export mappings in column order as RFC 4180 CSV, including the header.

    - rows: iterable of mappings (one-shot generators supported).
    - columns: ordered iterable of unique string column names.

    Returns a str with a header line and one record per row, using comma
    delimiters, CRLF record endings, minimal quoting, and quote doubling.
    Missing fields and None become empty strings; other values become
    str(value). Unselected fields are ignored. Duplicate or non-string
    column names raise ValueError. Inputs are not mutated.
    """
    cols = list(columns)
    seen = set()
    for col in cols:
        if not isinstance(col, str):
            raise ValueError(f"Column names must be strings, got {type(col).__name__}")
        if col in seen:
            raise ValueError(f"Duplicate column name: {col!r}")
        seen.add(col)

    def field_text(value):
        if value is None:
            return ""
        if isinstance(value, str):
            return value
        return str(value)

    def quote_field(text):
        if any(ch in text for ch in ("\r", "\n", '"', ",")):
            return '"' + text.replace('"', '""') + '"'
        return text

    lines = [",".join(quote_field(col) for col in cols)]
    for row in rows:
        lines.append(",".join(quote_field(field_text(row.get(col, ""))) for col in cols))
    return "\r\n".join(lines) + "\r\n"

