            export_csv([{"a": 'say "hi"\nbye', "b": "c,d"}], ["a", "b"]),
            'a,b\r\n"say ""hi""\nbye","c,d"\r\n',
        )

    def test_embedded_cr_preserved(self):
        self.assertEqual(
            export_csv([{"a": "x\ry"}], ["a"]),
            'a\r\n"x\ry"\r\n',
        )

    def test_unicode_preserved(self):
        self.assertEqual(
            export_csv([{"a": "héllo\u2603"}], ["a"]),
            "a\r\nhéllo\u2603\r\n",
