"""Optional tests for reports.export.export_csv."""
import unittest

from reports import export_csv


class ExportCsvTests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(
            export_csv([{"a": 1, "b": "x"}, {"a": 2, "b": "y"}], ["a", "b"]),
            "a,b\r\n1,x\r\n2,y\r\n",
        )

    def test_missing_and_none_become_empty(self):
        self.assertEqual(
            export_csv([{"a": None}], ["a", "b"]),
            "a,b\r\n,\r\n",
        )

    def test_quote_doubling_and_embedded_newlines(self):
        self.assertEqual(
            export_csv([{"a": 'say "hi"\nbye', "b": "c,d"}], ["a", "b"]),
            'a,b\r\n"say ""hi""\nbye","c,d"\r\n',
        )

    def test_embedded_cr_preserved(self):
        self.assertEqual(
            export_csv([{"a": "x\ry"}], ["a"]),
            'a\r\n"x\ry"\r\n',
        )

    def test_unicode_preserved(self):
        self.assertEqual(
            export_csv([{"a": "héllo\u2603"}], ["a"]),
            "a\r\nhéllo\u2603\r\n",
        )

    def test_unselected_fields_ignored(self):
        self.assertEqual(
            export_csv([{"a": 1, "z": 99}], ["a"]),
            "a\r\n1\r\n",
        )

    def test_one_shot_generators(self):
        rows = iter([{"a": 1}, {"a": 2}])
        cols = (c for c in ["a"])
        self.assertEqual(export_csv(rows, cols), "a\r\n1\r\n2\r\n")

    def test_empty_rows(self):
        self.assertEqual(export_csv([], ["a", "b"]), "a,b\r\n")

    def test_empty_columns(self):
        # Header line plus one (empty) record per row.
        self.assertEqual(export_csv([{"a": 1}, {}], []), "\r\n\r\n\r\n")
        self.assertEqual(export_csv([], []), "\r\n")

    def test_duplicate_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], ["a", "a"])

    def test_non_string_columns_rejected(self):
        with self.assertRaises(ValueError):
            export_csv([], [1])
        with self.assertRaises(ValueError):
            export_csv([], [None])

    def test_values_stringified(self):
        self.assertEqual(
            export_csv([{"a": 1.5, "b": True}], ["a", "b"]),
            "a,b\r\n1.5,True\r\n",
        )

    def test_inputs_not_mutated(self):
        rows = [{"a": 1}]
        cols = ["a"]
        export_csv(rows, cols)
        self.assertEqual(rows, [{"a": 1}])
        self.assertEqual(cols, ["a"])


if __name__ == "__main__":
